//--- VIOC crew_ffv (parche de VIOC; no es del autor de la mision): sin tripulantes en los puestos FFV de pasajero
//--- (CargoTurret; p. ej. la caja de las Toyota de Toyota's Of War: un Hilux GMG salia con 6 hombres).
_turrets = _turrets select {
	private _tc = _config select (_x select 0);
	if (count _x > 1) then {_tc = (_tc >> "turrets") select (_x select 1)};
	!(isClass _tc) || {(([_tc, true] call BIS_fnc_returnParents) findIf {_x == "CargoTurret"}) < 0}
};
